cat > src/promotions.ts <<'EOF'
export type Promotion = (
  | { code: string; kind: "percent"; percent: number }
  | { code: string; kind: "fixed"; amountCents: number }
  | { code: string; kind: "multibuy"; sku: string; buy: number; pay: number }
) & {
  /** Coupon is only valid when the subtotal is at least this amount. */
  minSubtotalCents?: number;
};

export interface PricedLine {
  sku: string;
  qty: number;
  unitCents: number;
  lineCents: number;
}

export function findPromotion(promotions: Promotion[], code: string): Promotion {
  const promotion = promotions.find((p) => p.code === code);
  if (!promotion) throw new Error(`Unknown coupon code: ${code}`);
  return promotion;
}

/** Discount in cents that a promotion grants on the given lines (never more than their sum). */
export function discountFor(promotion: Promotion, lines: PricedLine[]): number {
  const subtotal = lines.reduce((sum, l) => sum + l.lineCents, 0);
  return Math.min(rawDiscount(promotion, lines, subtotal), subtotal);
}

function rawDiscount(promotion: Promotion, lines: PricedLine[], subtotal: number): number {
  switch (promotion.kind) {
    case "percent":
      return Math.round((subtotal * promotion.percent) / 100);
    case "fixed":
      return promotion.amountCents;
    case "multibuy": {
      const matching = lines.filter((l) => l.sku === promotion.sku);
      if (matching.length === 0) return 0;
      const qty = matching.reduce((sum, l) => sum + l.qty, 0);
      const groups = Math.floor(qty / promotion.buy);
      return groups * (promotion.buy - promotion.pay) * matching[0].unitCents;
    }
  }
}
EOF

python3 - <<'EOF'
p='src/checkout.ts'
s=open(p).read()
s=s.replace('import { roundToRappen, vatIncluded } from "./money";','import { formatChf, roundToRappen, vatIncluded } from "./money";')
s=s.replace('''  vat: Record<VatCategory, number>;
}''','''  vat: Record<VatCategory, number>;
  /** Message for the customer, e.g. a coupon that could not be applied. */
  notice?: string;
}''')
s=s.replace('lineCents: roundToRappen(product.priceCents * qty),','lineCents: product.priceCents * qty,')
old=s[s.index('  let discountCents = 0;'):]
new='''  let discountCents = 0;
  let notice: string | undefined;
  if (couponCode !== undefined) {
    const promotion = findPromotion(promotions, couponCode);
    if (promotion.minSubtotalCents !== undefined && subtotalCents < promotion.minSubtotalCents) {
      notice = `Coupon ${couponCode} requires a minimum order of ${formatChf(promotion.minSubtotalCents)}`;
    } else {
      discountCents = discountFor(promotion, lines);
    }
  }

  const gross: Record<VatCategory, number> = { standard: 0, reduced: 0 };
  for (const l of lines) gross[l.vat] += l.lineCents;

  // Split the discount between the rates in proportion to their share of the subtotal.
  const reducedDiscount =
    subtotalCents > 0 ? Math.round((discountCents * gross.reduced) / subtotalCents) : 0;
  const discountShare: Record<VatCategory, number> = {
    reduced: reducedDiscount,
    standard: discountCents - reducedDiscount,
  };

  const vat: Record<VatCategory, number> = { standard: 0, reduced: 0 };
  for (const category of Object.keys(vat) as VatCategory[]) {
    vat[category] = vatIncluded(gross[category] - discountShare[category], VAT_RATES[category]);
  }

  return {
    lines,
    subtotalCents,
    couponCode,
    discountCents,
    totalCents: roundToRappen(subtotalCents - discountCents),
    vat,
    ...(notice !== undefined && { notice }),
  };
}
'''
s=s.replace(old,new)
open(p,'w').write(s)

